def write_pairs(output_path: Path):
    output_path.parent.mkdir(parents=True, exist_ok=True)
    with open(output_path, "w", encoding="utf-8") as f:
        for p in PAIRS:
            f.write(json.dumps(p) + "\n")
    print(f"Successfully generated {len(PAIRS)} labeled pairs in {output_path}")


if __name__ == "__main__":
    out = Path("benchmarks/labels/resolution_pairs.jsonl")
    write_pairs(out)
